using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change: EF Core 9 no longer uses HasData with DateTime.UtcNow
        // (non-deterministic seed data). Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---
class CosmosDbContext : DbContext
{
    public DbSet<Document> Documents => Set<Document>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "https://localhost:8081",
            "key",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change #1: EF Core 9 Cosmos provider renamed the discriminator
        // property from "Discriminator" to "$type". Existing documents use "Discriminator",
        // so we must explicitly configure it to preserve backward compatibility.
        modelBuilder.Entity<Document>().HasDiscriminator<string>("Discriminator");

        modelBuilder.Entity<Document>().ToContainer("Documents");
    }
}

class Document
{
    public string Id { get; set; } = default!;
    public string Title { get; set; } = default!;
}

// --- Cosmos query service demonstrating sync query removal ---
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // Breaking change #2: EF Core 9 Cosmos provider removed synchronous query
    // support (ToList, First, Single, etc. all throw).
    // All Cosmos queries MUST be async now.
    public async Task<List<Document>> GetDocumentsAsync()
    {
        // BEFORE (EF Core 8 - no longer works in EF Core 9):
        //   return _db.Documents.ToList();
        //
        // AFTER (EF Core 9 - must use async):
        return await _db.Documents.ToListAsync();
    }

    public async Task<Document?> GetByIdAsync(string id)
    {
        // BEFORE: return _db.Documents.FirstOrDefault(d => d.Id == id);
        // AFTER:
        return await _db.Documents.FirstOrDefaultAsync(d => d.Id == id);
    }
}

